(function (global, factory) {
  typeof exports === 'object' && typeof module !== 'undefined' ? module.exports = factory() :
  typeof define === 'function' && define.amd ? define(factory) :
  (global = typeof globalThis !== 'undefined' ? globalThis : global || self, global.Chart = factory());
})(this, function () {
  'use strict';

  // ---- Minimal Color Helpers ----
  function parseColor(c) {
    if (c.startsWith('#')) {
      const r = parseInt(c.slice(1,3),16), g = parseInt(c.slice(3,5),16), b = parseInt(c.slice(5,7),16);
      return {r,g,b,a:1};
    }
    if (c.startsWith('rgba')) {
      const m = c.match(/rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)/);
      return m ? {r:+m[1],g:+m[2],b:+m[3],a:+m[4]} : {r:0,g:0,b:0,a:1};
    }
    return {r:100,g:100,b:255,a:0.8};
  }

  // ---- Layout ----
  function calcLayout(canvas, config) {
    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;
    const legend = config.options?.plugins?.legend;
    const legendH = (legend?.display !== false) ? 32 : 0;
    const pad = {top: 16 + legendH, right: 24, bottom: 40, left: 60};
    return { ctx, w, h, pad,
      chartW: w - pad.left - pad.right,
      chartH: h - pad.top - pad.bottom };
  }

  // ---- Text helpers ----
  function setFont(ctx, size=12, weight='normal', family='Inter,system-ui,sans-serif') {
    ctx.font = `${weight} ${size}px ${family}`;
  }

  // ---- Bar Chart ----
  function drawBar(canvas, config) {
    const { ctx, w, h, pad, chartW, chartH } = calcLayout(canvas, config);
    ctx.clearRect(0,0,w,h);
    const ds = config.data.datasets[0];
    const labels = config.data.labels;
    const vals = ds.data;
    const max = Math.max(...vals, 1) * 1.15;
    const colors = Array.isArray(ds.backgroundColor)
      ? ds.backgroundColor
      : Array(vals.length).fill(ds.backgroundColor || '#6366f1');
    const barW = Math.min((chartW / vals.length) * 0.65, 60);
    const gap  = chartW / vals.length;

    // Grid
    ctx.strokeStyle = 'rgba(255,255,255,0.07)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = pad.top + chartH - (i/5) * chartH;
      ctx.beginPath(); ctx.moveTo(pad.left, y); ctx.lineTo(pad.left + chartW, y); ctx.stroke();
      setFont(ctx, 10); ctx.fillStyle = 'rgba(255,255,255,0.45)'; ctx.textAlign = 'right';
      ctx.fillText(Math.round((i/5)*max), pad.left - 6, y + 4);
    }

    // Bars
    vals.forEach((v, i) => {
      const x  = pad.left + gap*i + (gap - barW)/2;
      const bh = (v / max) * chartH;
      const y  = pad.top + chartH - bh;
      const col = parseColor(colors[i] || '#6366f1');
      const grad = ctx.createLinearGradient(x, y, x, y + bh);
      grad.addColorStop(0, `rgba(${col.r},${col.g},${col.b},0.9)`);
      grad.addColorStop(1, `rgba(${col.r},${col.g},${col.b},0.4)`);
      ctx.fillStyle = grad;
      const r = Math.min(6, barW/2);
      ctx.beginPath();
      ctx.roundRect ? ctx.roundRect(x, y, barW, bh, [r, r, 0, 0])
                    : ctx.rect(x, y, barW, bh);
      ctx.fill();
      // Label
      setFont(ctx, 9); ctx.fillStyle = 'rgba(255,255,255,0.55)'; ctx.textAlign = 'center';
      const lbl = (labels[i] || '').toString();
      const short = lbl.length > 10 ? lbl.slice(0,9)+'…' : lbl;
      ctx.fillText(short, x + barW/2, pad.top + chartH + 14);
      // Value on top
      if (v > 0) {
        setFont(ctx, 9, 'bold'); ctx.fillStyle = 'rgba(255,255,255,0.8)';
        ctx.fillText(v, x + barW/2, y - 4);
      }
    });
    drawTitle(ctx, config, w);
  }

  // ---- Doughnut Chart ----
  function drawDoughnut(canvas, config) {
    const { ctx, w, h } = calcLayout(canvas, config);
    ctx.clearRect(0,0,w,h);
    const ds = config.data.datasets[0];
    const labels = config.data.labels;
    const vals = ds.data;
    const total = vals.reduce((a,b)=>a+b,0) || 1;
    const colors = ds.backgroundColor || ['#6366f1','#22d3ee','#f59e0b','#10b981','#ef4444'];
    const cx = w/2, cy = h/2 - 10;
    const outerR = Math.min(cx, cy) * 0.72;
    const innerR = outerR * 0.58;
    let angle = -Math.PI/2;

    vals.forEach((v, i) => {
      const slice = (v/total) * Math.PI*2;
      const col = parseColor(colors[i % colors.length]);
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, outerR, angle, angle+slice);
      ctx.closePath();
      ctx.fillStyle = `rgba(${col.r},${col.g},${col.b},0.88)`;
      ctx.fill();
      ctx.strokeStyle = 'rgba(15,20,40,0.6)'; ctx.lineWidth = 2; ctx.stroke();
      angle += slice;
    });

    // Inner hole
    ctx.beginPath(); ctx.arc(cx, cy, innerR, 0, Math.PI*2);
    ctx.fillStyle = '#0f1428'; ctx.fill();

    // Center text
    setFont(ctx, 22, 'bold'); ctx.fillStyle = '#fff'; ctx.textAlign = 'center';
    ctx.fillText(total, cx, cy + 8);
    setFont(ctx, 10); ctx.fillStyle = 'rgba(255,255,255,0.5)';
    ctx.fillText('Total', cx, cy + 22);

    // Legend
    const legendY = cy + outerR + 12;
    const cols = Math.min(vals.length, 4);
    const colW = w / cols;
    vals.forEach((v, i) => {
      const lx = (i % cols) * colW + 12;
      const ly = legendY + Math.floor(i/cols)*18;
      const col = parseColor(colors[i % colors.length]);
      ctx.fillStyle = `rgba(${col.r},${col.g},${col.b},0.9)`;
      ctx.fillRect(lx, ly, 10, 10);
      setFont(ctx, 9); ctx.fillStyle = 'rgba(255,255,255,0.65)'; ctx.textAlign = 'left';
      const lbl = (labels[i]||'').toString();
      ctx.fillText(`${lbl.slice(0,14)} (${v})`, lx+14, ly+9);
    });
    drawTitle(ctx, config, w);
  }

  // ---- Line Chart ----
  function drawLine(canvas, config) {
    const { ctx, w, h, pad, chartW, chartH } = calcLayout(canvas, config);
    ctx.clearRect(0,0,w,h);
    const ds = config.data.datasets[0];
    const labels = config.data.labels;
    const vals = ds.data;
    const max = Math.max(...vals, 1) * 1.15;

    // Grid
    for (let i = 0; i <= 4; i++) {
      const y = pad.top + chartH - (i/4)*chartH;
      ctx.strokeStyle = 'rgba(255,255,255,0.07)'; ctx.lineWidth=1;
      ctx.beginPath(); ctx.moveTo(pad.left,y); ctx.lineTo(pad.left+chartW,y); ctx.stroke();
      setFont(ctx,10); ctx.fillStyle='rgba(255,255,255,0.4)'; ctx.textAlign='right';
      ctx.fillText(Math.round((i/4)*max), pad.left-6, y+4);
    }

    const step = chartW / Math.max(vals.length-1, 1);
    const pts = vals.map((v,i)=>({x: pad.left+i*step, y: pad.top+chartH-(v/max)*chartH}));

    // Area fill
    const col = parseColor(ds.borderColor || '#6366f1');
    const grad = ctx.createLinearGradient(0, pad.top, 0, pad.top+chartH);
    grad.addColorStop(0, `rgba(${col.r},${col.g},${col.b},0.3)`);
    grad.addColorStop(1, `rgba(${col.r},${col.g},${col.b},0.02)`);
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pad.top+chartH);
    pts.forEach(p=>ctx.lineTo(p.x,p.y));
    ctx.lineTo(pts[pts.length-1].x, pad.top+chartH);
    ctx.closePath(); ctx.fillStyle=grad; ctx.fill();

    // Line
    ctx.beginPath();
    pts.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
    ctx.strokeStyle=`rgba(${col.r},${col.g},${col.b},0.9)`; ctx.lineWidth=2.5; ctx.stroke();

    // Points
    pts.forEach(p=>{
      ctx.beginPath(); ctx.arc(p.x,p.y,4,0,Math.PI*2);
      ctx.fillStyle=`rgba(${col.r},${col.g},${col.b},1)`; ctx.fill();
      ctx.strokeStyle='rgba(15,20,40,0.8)'; ctx.lineWidth=2; ctx.stroke();
    });

    // X labels
    labels.forEach((l,i)=>{
      setFont(ctx,9); ctx.fillStyle='rgba(255,255,255,0.45)'; ctx.textAlign='center';
      ctx.fillText(l, pts[i].x, pad.top+chartH+14);
    });
    drawTitle(ctx, config, w);
  }

  function drawTitle(ctx, config, w) {
    const title = config.options?.plugins?.title;
    if (title?.display && title.text) {
      setFont(ctx, 13, '600'); ctx.fillStyle='rgba(255,255,255,0.85)'; ctx.textAlign='center';
      ctx.fillText(title.text, w/2, 16);
    }
  }

  // ---- Chart class ----
  class Chart {
    constructor(canvas, config) {
      this.canvas = typeof canvas === 'string' ? document.getElementById(canvas) : canvas;
      this.config = config;
      this.type = config.type;
      this._destroyed = false;
      this._render();
    }

    _render() {
      if (this._destroyed) return;
      if (this.type === 'bar')      drawBar(this.canvas, this.config);
      else if (this.type === 'doughnut' || this.type === 'pie') drawDoughnut(this.canvas, this.config);
      else if (this.type === 'line') drawLine(this.canvas, this.config);
    }

    update() { this._render(); }

    destroy() {
      this._destroyed = true;
      const ctx = this.canvas.getContext('2d');
      ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    }

    static register() {}   // no-op: compatibility shim
    static defaults = { responsive: true };
  }

  return Chart;
});
